function draw(){if(!window.L){$('map').textContent='Peta tidak tersedia. Gunakan Senarai untuk meneruskan misi.';return}map=L.map('map',{zoomControl:false,minZoom:8,maxZoom:19});L.control.zoom({position:'topright'}).addTo(map);L.control.scale({imperial:false,position:'bottomright'}).addTo(map);const tiles=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a>'}).addTo(map);let failures=0;tiles.on('tileerror',()=>{if(++failures===4)$('gameStatus').textContent='Latar peta belum tersedia. Misi boleh diteruskan melalui Senarai.'});markerLayer=L.markerClusterGroup?L.markerClusterGroup({maxClusterRadius:24,showCoverageOnHover:false,spiderfyOnMaxZoom:true,iconCreateFunction:c=>L.divIcon({className:'site-cluster-shell',html:`<span class="site-cluster">${c.getChildCount()}</span>`,iconSize:[40,40]})}):L.layerGroup();markerLayer.addTo(map);map.on?.('dragstart',()=>setStageFollow(false));fitAll();moveAvatar(false);for(const port of MARINE_DATA.jetties)L.marker([port.lat,port.lng],{icon:L.divIcon({className:"jetty-pin-shell",html:`<span class="jetty-pin">⚓ ${port.id}</span>`,iconSize:[64,36],iconAnchor:port.kind==='island'?[-6,36]:[32,36]}),title:port.name}).addTo(map).on("click",()=>openJetty(port))}
