function paintJourney(state){if(!journey)return;const to=sites.find(s=>s.id===journey.toId),mode=TRANSPORTS[state.mode||journey.route.mode||'car'];$('travelPortrait').innerHTML=profile?`<img src="${characters[profile.avatar].image}" alt="">`:'<span>🧭</span>';$('travelRoute').textContent=`${journey.fromId} · ${journey.toId} / ${state.waiting?'MENUNGGU BAS':mode.name.toUpperCase()} · MASA 3:1`;$('travelDestination').textContent=to.name;$('travelProgress').value=Math.round(state.fraction*100);$('travelRemaining').textContent=formatClock(state.remainingMs);$('travelStats').textContent=`${journey.pausedAt!==null?'Dijeda · ':''}${(journey.route.distanceMetres/1000).toFixed(1)} km · ${mode.name.toLowerCase()} ≈ ${formatClock(journey.route.durationSeconds*1000)}`;$('pauseJourney').textContent=journey.pausedAt!==null?'Sambung':'Jeda';$('journeyBanner').hidden=false;if(map){if(!avatar)moveAvatar(false);avatar?.setLatLng(state.position);travelledRoute?.setLatLngs([...journey.route.path.slice(0,state.index+1),state.position])}$('gameStatus').textContent=`${journey.pausedAt!==null?'Perjalanan dijeda':state.waiting?'Menunggu bas jelajah':'Dalam perjalanan'} ke ${journey.toId} · baki ${formatClock(state.remainingMs)}. ${journey.pausedAt!==null?'Tekan Sambung untuk meneruskan.':'Masa terus berjalan walaupun web ditutup.'}`;paintStage(state);if($('inlineRemaining'))$('inlineRemaining').textContent=formatClock(state.remainingMs);const total=rewardTotals(rewards);$('travelReward').textContent=`XP perjalanan: ${total.xp} · +10 XP selepas ${formatClock(total.remainingMs)} bergerak lagi`;}
function finishJourney(openMission=true){if(!journey||!journeyAt(journey).arrived)return false;syncTravelRewards();const trip=journey;gameSound.play('arrive',{key:`arrive:${trip.startedAt}:${trip.toId}`});journey=null;stopTravelTimer();playerId=trip.toId;const arrivedAt=Math.min(Date.now(),trip.startedAt+trip.pausedMs+Math.ceil(trip.route.durationSeconds/TIME_RATIO*1000));records[playerId]={...records[playerId],arrived:records[playerId]?.arrived||arrivedAt};$('journeyBanner').hidden=true;showStageArrival(trip.toId);if(plannedRoute&&map){map.removeLayer(plannedRoute);plannedRoute=null}travelledRoute?.setLatLngs(trip.route.path);save();moveAvatar(false);render();$('gameStatus').textContent=`Anda tiba di ${playerId}. Cabaran sedia dibuka.`;const target=sites.find(s=>s.id===playerId);if(selected?.id===playerId&&$('detail').open)detail();else if(openMission&&!document.hidden&&!$('detail').open&&!$('profileDialog').open&&!$('guideDialog').open&&!$('certificateDialog').open)openSite(target,'mission');toast(`Tiba di ${playerId} · perjalanan selesai.`);return true}
