function runGuideAction(advice){$('guideDialog').close();if(advice.action==='profile'){if($('detail').open)$('detail').close();openProfile();return}if(advice.action==='resume'||advice.action==='journey'){if(journey){if(advice.action==='resume'&&journey.pausedAt!==null)togglePause();focusJourney()}else{const site=sites.find(s=>s.id===advice.target);if(site)openSite(site,'mission')}return}if(advice.action==='shop'){goShop();return}if(advice.action==='collection'){if($('detail').open)$('detail').close();selectPage('passport');setPassportView('collection');return}if(advice.action==='site'||advice.action==='challenge'){const site=sites.find(s=>s.id===advice.target);if(site)openSite(site,advice.action==='challenge'?'mission':'info');return}selectPage('map');setView('map');fitAll()}
